38	const TICK_INTERVAL_MS = 60_000;
39	const RENEW_HEADROOM_MS = 55 * 60 * 1000;
40	const MAX_TOKEN_BACKOFF_MS = 15 * 60 * 1000;
41	const HOST_SETTINGS_ID = 1;
42	const GLOBAL_WARNING_KEY = "__global__";
43	const WORKSPACE_REFRESH_CONCURRENCY = 6;
