58	export interface WorkspaceClaudeAccountState {
59		workspaceId: string;
60		state: "following" | "pinned";
61		slug: string | null;
62		warning: { kind: "credential-health"; message: string } | null;
63	}
64	
65	export interface WorkspaceDeletionTarget {
66		workspaceId: string;
67		terminalIds: readonly string[];
68	}
69	
70	/**
71	 * (WORKTREE-EXIT-CLEANUP) What retiring a workspace's runtime actually did on
72	 * THIS host. The renderer broadcasts the retirement to every connected host,
73	 * so `foundWorkspace: false` is the ordinary answer from a host that does not
74	 * own the workspace, not a failure.
75	 */
76	export interface WorkspaceRuntimeRetirement {
77		/** False when this host has no row for the workspace. */
78		foundWorkspace: boolean;
79		/** Terminal ids whose disposal completed. */
80		terminated: string[];
81		/** Terminal ids whose disposal did not complete; the pin is cleared anyway. */
82		failed: string[];
83		/** True when this call cleared a pin; false when it was already Following. */
84		accountReleased: boolean;
85	}
