87	export interface ClaudeAccountsService {
88		start(): Promise<void>;
89		stop(): void;
90		mintProfileForNewWorkspace(workspaceId: string): Promise<void>;
91		ensureProfileForLaunch(workspaceId: string): Promise<string>;
92		profileDirFor(workspaceId: string): string;
93		configDirCandidatesFor(workspaceId: string): string[];
94		setWorkspaceAccount(workspaceId: string, slug: string | null): Promise<void>;
95		retireWorkspaceRuntime(
96			workspaceId: string,
97		): Promise<WorkspaceRuntimeRetirement>;
98		getWorkspaceState(
99			workspaceId: string,
100		): Promise<Omit<WorkspaceClaudeAccountState, "workspaceId">>;
101		getWorkspaceStates(): Promise<WorkspaceClaudeAccountState[]>;
102		getRoster(): Promise<{
103			trayDefaultSlug: string | null;
104			accounts: ClaudeAccountRosterEntry[];
105		}>;
106		getCapability(): { managed: boolean; configured: boolean };
107		withWorkspaceDeletion<T>(
108			targets: readonly WorkspaceDeletionTarget[],
109			fn: () => Promise<T>,
110			opts: { disposalMode: DisposalFailureMode; timeoutMs?: number },
111		): Promise<T>;
112		withWorkspaceLocks<T>(
113			workspaceIds: string[],
114			fn: () => Promise<T>,
115			opts?: { timeoutMs?: number },
116		): Promise<T>;
117		withWorkspaceLock<T>(
118			workspaceId: string,
119			fn: () => Promise<T>,
120			opts?: { tryOnly?: boolean; timeoutMs?: number },
121		): Promise<T>;
122	}
123	
124	interface TokenBackoff {
125		failures: number;
126		nextAttemptAt: number;
127	}
128	
129	type CredentialTransition =
130		| { credentialAction: "write"; credentials: ManagedCredentials }
131		| { credentialAction: "remove" }
132		| { credentialAction: "keep" };
133	
134	interface AccountTransitionBase {
135		desiredSlug: string | null;
136		ensureProfile?: { worktreePath: string; knownExists?: boolean };
137		database?:
138			| { kind: "set"; currentSlug: string | null }
139			| { kind: "compare-and-set"; expectedSlug: string };
140		cause: "manual" | "auto-fallback" | "system";
141	}
142	
143	type AccountTransition = AccountTransitionBase & CredentialTransition;
144	
145	class ClaudeAccountsServiceImpl implements ClaudeAccountsService {
146		private readonly locks = new WorkspaceLocks();
147		private readonly profiles: ClaudeProfileManager;
148		private readonly pi: PiClient;
149		private readonly fallback: FallbackPolicy;
150		private janitor: ClaudeProfileJanitor | null = null;
151		private dbInstanceId: string | null = null;
152		private configured = false;
153		private managed = false;
154		private managedLatchPersisted = false;
155		private started = false;
156		private degraded = false;
157		private stopped = false;
158		private interval: ReturnType<typeof setInterval> | null = null;
159		private credentialsWatcher: FSWatcher | null = null;
160		private tickInFlight: Promise<void> | null = null;
161		private tickCount = 0;
162		private readonly tokenBackoffs = new Map<string, TokenBackoff>();
163		private readonly credentialCache = new Map<
164			string,
165			ManagedCredentials | null
166		>();
167		private readonly warningCauses = new Map<string, Map<string, string>>();
168	
169		constructor(private readonly deps: ClaudeAccountsServiceDeps) {
170			this.profiles = new ClaudeProfileManager(deps.dbPath, deps.log);
171			this.pi = new PiClient(deps.log, {
172				...(deps.piBaseUrl !== undefined ? { baseUrl: deps.piBaseUrl } : {}),
173				...(deps.pushKeyPath !== undefined
174					? { pushKeyPath: deps.pushKeyPath }
175					: {}),
176			});
177			this.fallback = new FallbackPolicy(deps.log);
178		}
179	
180		async start(): Promise<void> {
181			if (this.started && !this.stopped) return;
182			if (this.stopped) {
183				throw new Error(
184					"Claude accounts service cannot be restarted after stop()",
185				);
186			}
187			const settings = this.ensureDatabaseInstance();
188			this.dbInstanceId = settings.dbInstanceId;
189			this.managedLatchPersisted = settings.managedLatch;
190			const workspaceRows = this.deps.db.select().from(workspaces).all();
191			let profileStateExists: boolean;
192			try {
193				await this.profiles.initialize();
194				profileStateExists = await this.hasManagedProfileState();
195			} catch (error) {
196				this.degraded = true;
197				this.deps.log.error(
198					"Claude profile storage failed to initialize; account management is disabled",
199					{ error },
200				);
201				this.setWarningCause(
202					null,
203					"profile-root",
204					"Claude workspace profile storage is unavailable. Account management is disabled.",
205				);
206				this.managed = false;
207				this.configured = await this.refreshPushKeyHealth({ emitWarning: false });
208				this.started = true;
209				return;
210			}
211			const pushKeyPathExists = existsSync(this.pi.getPushKeyPath());
212			this.configured = await this.refreshPushKeyHealth({ emitWarning: false });
213			const pinnedStateExists = workspaceRows.some(
214				(row) => row.claudeAccountSlug !== null,
215			);
216			if ((profileStateExists || pinnedStateExists) && !settings.managedLatch) {
217				this.persistManagedLatch();
218			}
219			this.managed =
220				pushKeyPathExists ||
221				settings.managedLatch ||
222				profileStateExists ||
223				pinnedStateExists;
224	
225			this.janitor = new ClaudeProfileJanitor({
226				db: this.deps.db,
227				dbInstanceId: this.dbInstanceId,
228				profiles: this.profiles,
229				log: this.deps.log,
230				withWorkspaceLock: (workspaceId, fn, opts) =>
231					this.withWorkspaceLock(workspaceId, fn, opts),
232				deleteProfileWithTerminalIds: (workspaceId, terminalIds) =>
233					this.deleteProfileWithTerminalIds(workspaceId, terminalIds),
234			});
235	
236			if (this.managed) {
237				clearLegacyClaudeDefaultAccount(this.deps.db);
238				this.startCredentialsWatcher();
239				if (!this.configured) {
240					this.setWarningCause(
241						null,
242						"push-key",
243						"Claude account management is active, but the Pi push key is unavailable or invalid.",
244					);
245				}
246			}
247	
248			this.started = true;
249			const initialWork = this.runInitialBackgroundWork(
250				workspaceRows.map((row) => row.id),
251			);
252			if (this.deps.awaitInitialBackgroundWork) await initialWork;
253			else void initialWork;
254			this.interval = setInterval(() => {
255				void this.runTick().catch((error) => {
256					this.deps.log.error("Claude account keep-fresh tick failed", { error });
257				});
258			}, TICK_INTERVAL_MS);
259			this.interval.unref();
260		}
261	
262		private async runInitialBackgroundWork(
263			workspaceIds: readonly string[],
264		): Promise<void> {
265			if (this.managed) {
266				const tasks = [
267					{
268						name: "profile sweep",
269						run: () => this.profiles.sweepProfiles(workspaceIds),
270					},
271					{
272						name: "credential cache seed",
273						run: () => this.seedTokenCache(workspaceIds),
274					},
275					{
276						name: "profile janitor",
277						run: () => this.requireJanitor().run(true),
278					},
279				] as const;
280				for (const task of tasks) {
281					try {
282						await task.run();
283					} catch (error) {
284						this.deps.log.error(`Claude account startup ${task.name} failed`, {
285							error,
286						});
287					}
288				}
289			}
290			try {
291				await this.runTick();
292			} catch (error) {
293				this.deps.log.error("Initial Claude account keep-fresh tick failed", {
294					error,
295				});
296			}
297		}
298	
299		stop(): void {
300			this.stopped = true;
301			if (this.interval) clearInterval(this.interval);
302			this.interval = null;
303			this.credentialsWatcher?.close();
304			this.credentialsWatcher = null;
305		}
306	
307		async mintProfileForNewWorkspace(workspaceId: string): Promise<void> {
308			if (!this.getCapability().managed) return;
309			await this.ensureProfileForLaunch(workspaceId);
310		}
311	
312		async ensureProfileForLaunch(workspaceId: string): Promise<string> {
313			if (!this.managed) {
314				throw new Error(
315					"Claude workspace profiles are not configured on this host",
316				);
317			}
318			return this.withWorkspaceLock(workspaceId, async () => {
319				const row = this.requireWorkspace(workspaceId);
320				const profileExists = await this.profiles.profileExists(workspaceId);
321				const current = await this.readProfileCredentialsForCache(
322					workspaceId,
323					profileExists,
324				);
325				const credentialTransition =
326					row.claudeAccountSlug !== null
327						? this.credentialsForPinnedLaunch(
328								workspaceId,
329								row.claudeAccountSlug,
330								current,
331							)
332						: await this.credentialsForFollowingLaunch(workspaceId);
333				await this.applyWorkspaceAccountTransition(workspaceId, {
334					desiredSlug: row.claudeAccountSlug,
335					...credentialTransition,
336					ensureProfile: {
337						worktreePath: row.worktreePath,
338						knownExists: profileExists,
339					},
340					cause: "system",
341				});
342				this.latchManaged();
343				return this.profiles.profileDirFor(workspaceId);
344			});
345		}
346	
347		profileDirFor(workspaceId: string): string {
348			return this.profiles.profileDirFor(workspaceId);
349		}
350	
351		configDirCandidatesFor(workspaceId: string): string[] {
352			if (!isWorkspaceUuid(workspaceId)) return [];
353			const globalDir =
354				process.env.CLAUDE_CONFIG_DIR ?? this.profiles.globalClaudeDir;
355			if (!this.managed) return [globalDir];
356			const workspaceDir = this.profiles.profileDirFor(workspaceId);
357			const candidates = existsSync(workspaceDir)
358				? [workspaceDir, globalDir]
359				: [globalDir];
360			return [...new Set(candidates)];
361		}
362	
363		async setWorkspaceAccount(
364			workspaceId: string,
365			slug: string | null,
366		): Promise<void> {
367			if (!this.managed) {
368				throw new Error(
369					"Claude account switching is not configured on this host",
370				);
371			}
372			await this.withWorkspaceLock(workspaceId, async () => {
373				const row = this.requireWorkspace(workspaceId);
374				if (slug !== null) validateAccountSlug(slug);
375				let roster: PiAccount[];
376				try {
377					roster = await this.pi.fetchAccounts();
378				} catch (error) {
379					if (slug === null) {
380						throw new Error(
381							"Cannot switch this workspace to Following while the Pi is unavailable",
382							{ cause: error },
383						);
384					}
385					throw error;
386				}
387				let credentialTransition: CredentialTransition;
388				if (slug !== null) {
389					const account = findClaudeAccount(roster, slug);
390					if (!account)
391						throw new Error(`Claude account ${slug} is not in the Pi roster`);
392					const accountHealth = accountHealthMessage(
393						account,
394						`Claude account '${slug}'`,
395					);
396					if (accountHealth) throw new Error(accountHealth);
397					const token = await this.pi.fetchToken(slug);
398					credentialTransition = {
399						credentialAction: "write",
400						credentials: credentialsFromToken(token),
401					};
402				} else {
403					let identity: GlobalIdentity;
404					try {
405						identity = await this.profiles.readGlobalIdentity();
406					} catch (error) {
407						this.setWarningCause(
408							workspaceId,
409							"machine-default",
410							"The machine-default Claude credentials are unreadable. The account change was not saved.",
411						);
412						throw new Error(
413							"Cannot switch this workspace to Following while the machine-default Claude credentials are unreadable",
414							{ cause: error },
415						);
416					}
417					credentialTransition =
418						identity.kind === "absent"
419							? { credentialAction: "keep" }
420							: {
421									credentialAction: "write",
422									credentials: identity.credentials,
423								};
424					this.setWarningCause(
425						workspaceId,
426						"machine-default",
427						identity.kind === "absent"
428							? "The machine default is signed out. This workspace will keep its last-good token."
429							: null,
430					);
431				}
432				if (row.claudeAccountSlug !== slug) {
433					this.credentialCache.delete(workspaceId);
434				}
435				await this.applyWorkspaceAccountTransition(workspaceId, {
436					desiredSlug: slug,
437					...credentialTransition,
438					ensureProfile: { worktreePath: row.worktreePath },
439					database: { kind: "set", currentSlug: row.claudeAccountSlug },
440					cause: "manual",
441				});
442				this.latchManaged();
443			});
444		}
445	
446		/**
447		 * (WORKTREE-EXIT-CLEANUP) Stop everything this workspace is running and
448		 * hand its Claude account back, because the user has exited the workspace.
449		 *
450		 * System-only and idempotent: it never asks the Pi anything, so it works
451		 * with the Pi offline, and it deliberately does NOT gate on `managed` — a
452		 * host that lost its Pi capability can still be carrying a stale pin. An
453		 * unknown workspace answers `foundWorkspace: false` instead of throwing,
454		 * because the renderer broadcasts this to every connected host.
455		 *
456		 * The profile folder itself is left alone; only the credentials inside it
457		 * go, so a restored card starts again on the machine default.
458		 */
459		async retireWorkspaceRuntime(
460			workspaceId: string,
461		): Promise<WorkspaceRuntimeRetirement> {
462			return this.withWorkspaceLock(workspaceId, async () => {
463				const row = this.deps.db.query.workspaces
464					.findFirst({ where: eq(workspaces.id, workspaceId) })
465					.sync();
466				if (!row) {
467					return {
468						foundWorkspace: false,
469						terminated: [],
470						failed: [],
471						accountReleased: false,
472					};
473				}
474				// Opened before disposing: this and the row listing below are one
475				// synchronous step, so a launch in flight on this host either lands
476				// in that list or is refused at its own row insert. The window stays
477				// open across the account release too — a terminal started while the
478				// profile's credentials are being rewritten would come up against a
479				// half-released account — and closes in `finally` so a failure here
480				// cannot fence this workspace's terminals forever.
481				const endRetirement = beginWorkspaceRetirement(workspaceId);
482				try {
483					const { terminated, failed } = await disposeTerminalIds(
484						this.deps.db,
485						listUndisposedTerminalIdsByWorkspaceId(workspaceId, this.deps.db),
486						this.disposalOptions("warn-and-continue"),
487					);
488					// `remove` runs even for an already-Following workspace: the file
489					// is the only place a pinned token can outlive the pin, and the
490					// cache entry it writes makes a stale pinned token unusable from
491					// memory.
492					await this.applyWorkspaceAccountTransition(workspaceId, {
493						desiredSlug: null,
494						credentialAction: "remove",
495						database: { kind: "set", currentSlug: row.claudeAccountSlug },
496						cause: "system",
497					});
498					return {
499						foundWorkspace: true,
500						terminated,
501						failed,
502						accountReleased: row.claudeAccountSlug !== null,
503					};
504				} finally {
505					endRetirement();
506				}
507			});
508		}
509	
510		async getWorkspaceState(
511			workspaceId: string,
512		): Promise<Omit<WorkspaceClaudeAccountState, "workspaceId">> {
513			const row = this.requireWorkspace(workspaceId);
514			const { workspaceId: _workspaceId, ...state } = this.mapWorkspaceState(
515				workspaceId,
516				row.claudeAccountSlug,
517			);
518			return state;
519		}
520	
521		async getWorkspaceStates(): Promise<WorkspaceClaudeAccountState[]> {
522			return this.deps.db
523				.select({
524					workspaceId: workspaces.id,
525					slug: workspaces.claudeAccountSlug,
526				})
527				.from(workspaces)
528				.where(isNull(workspaces.archivedAt))
529				.all()
530				.map((row) => this.mapWorkspaceState(row.workspaceId, row.slug));
531		}
532	
533		async getRoster(): Promise<{
534			trayDefaultSlug: string | null;
535			accounts: ClaudeAccountRosterEntry[];
536		}> {
537			let accounts: PiAccount[];
538			try {
539				accounts = await this.pi.fetchAccounts();
540			} catch (error) {
541				const lastGood = this.pi.getAccountsLastGood();
542				if (!lastGood) throw error;
543				this.deps.log.warn(
544					"Serving last-good Claude account roster after Pi failure",
545					{
546						error,
547					},
548				);
549				accounts = lastGood;
550			}
551			let trayDefaultSlug: string | null = null;
552			try {
553				const identity = await this.profiles.readGlobalIdentity();
554				trayDefaultSlug = identity.kind === "tray" ? identity.slug : null;
555			} catch (error) {
556				this.deps.log.warn(
557					"Could not resolve tray default for Claude account roster",
558					{
559						error,
560					},
561				);
562			}
563			return {
564				trayDefaultSlug,
565				accounts: accounts
566					.filter((account) => account.type === "claude")
567					.map(
568						({
569							type: _type,
570							fableResetsAt: _fableReset,
571							fableInUse: _fableInUse,
572							...account
573						}) => account,
574					),
575			};
576		}
577	
578		getCapability(): { managed: boolean; configured: boolean } {
579			return {
580				managed: this.managed,
581				configured: this.configured,
582			};
583		}
584	
585		async withWorkspaceDeletion<T>(
586			targets: readonly WorkspaceDeletionTarget[],
587			fn: () => Promise<T>,
588			opts: { disposalMode: DisposalFailureMode; timeoutMs?: number },
589		): Promise<T> {
590			if (!this.started) {
591				throw new Error("Claude accounts service has not started");
592			}
593			const deletionTargets = targets.map((target) => ({
594				workspaceId: target.workspaceId,
595				terminalIds: [...target.terminalIds],
596			}));
597			const workspaceIds = deletionTargets.map((target) => target.workspaceId);
598			if (new Set(workspaceIds).size !== workspaceIds.length) {
599				throw new Error(
600					"Workspace deletion targets contain a duplicate workspace id",
601				);
602			}
603			const disposalOptions = this.disposalOptions(opts.disposalMode);
604			return this.withWorkspaceLocks(
605				workspaceIds,
606				async () => {
607					if (this.degraded) {
608						this.deps.log.warn(
609							"Claude profile storage is unavailable; workspace deletion will continue without profile markers",
610							{ workspaceIds },
611						);
612						await disposeTerminalIds(
613							this.deps.db,
614							deletionTargets.flatMap((target) => target.terminalIds),
615							disposalOptions,
616						);
617						return fn();
618					}
619					const janitor = this.requireJanitor();
620					const preparedIds: string[] = [];
621					try {
622						for (const target of deletionTargets) {
623							await janitor.prepareWorkspaceDeletion(
624								target.workspaceId,
625								target.terminalIds,
626							);
627							preparedIds.push(target.workspaceId);
628						}
629						await disposeTerminalIds(
630							this.deps.db,
631							deletionTargets.flatMap((target) => target.terminalIds),
632							disposalOptions,
633						);
634					} catch (error) {
635						await this.clearDeletionMarkersOrThrow(preparedIds, error);
636						throw error;
637					}
638	
639					let result: T;
640					try {
641						result = await fn();
642					} catch (error) {
643						const rolledBackIds = preparedIds.filter((workspaceId) => {
644							const row = this.deps.db.query.workspaces
645								.findFirst({ where: eq(workspaces.id, workspaceId) })
646								.sync();
647							return row !== undefined;
648						});
649						await this.clearDeletionMarkersOrThrow(rolledBackIds, error);
650						throw error;
651					}
652	
653					const deletions = await Promise.allSettled(
654						preparedIds.map((workspaceId) =>
655							this.deletePreparedProfile(workspaceId),
656						),
657					);
658					for (const [index, deletion] of deletions.entries()) {
659						if (deletion.status === "fulfilled") continue;
660						this.deps.log.warn(
661							"Workspace was deleted but its Claude profile remains for janitor retry",
662							{
663								workspaceId: preparedIds[index],
664								error: deletion.reason,
665							},
666						);
667					}
668					return result;
669				},
670				opts.timeoutMs !== undefined ? { timeoutMs: opts.timeoutMs } : undefined,
671			);
672		}
673	
674		withWorkspaceLocks<T>(
675			workspaceIds: string[],
676			fn: () => Promise<T>,
677			opts?: { timeoutMs?: number },
678		): Promise<T> {
679			for (const workspaceId of workspaceIds) {
680				if (!isWorkspaceUuid(workspaceId)) {
681					return Promise.reject(
682						new Error(`Invalid workspace UUID: ${workspaceId}`),
683					);
684				}
685			}
686			return this.locks.withLocks(workspaceIds, fn, opts);
687		}
688	
689		withWorkspaceLock<T>(
690			workspaceId: string,
691			fn: () => Promise<T>,
692			opts?: { tryOnly?: boolean; timeoutMs?: number },
693		): Promise<T> {
694			if (!isWorkspaceUuid(workspaceId)) {
695				return Promise.reject(
696					new Error(`Invalid workspace UUID: ${workspaceId}`),
697				);
698			}
699			return this.locks.withLock(workspaceId, fn, opts);
700		}
701	
702		private runTick(): Promise<void> {
703			if (!this.managed || this.stopped) return Promise.resolve();
704			if (this.tickInFlight) return this.tickInFlight;
705			const tick = this.executeTick().finally(() => {
706				if (this.tickInFlight === tick) this.tickInFlight = null;
707			});
708			this.tickInFlight = tick;
709			return tick;
710		}
711	
712		private async executeTick(): Promise<void> {
713			this.tickCount += 1;
714			this.configured = await this.refreshPushKeyHealth({ emitWarning: true });
715	
716			let identity: GlobalIdentity | null = null;
717			try {
718				identity = await this.profiles.readGlobalIdentity();
719				if (identity.kind === "tray") {
720					this.pi.rememberToken({
721						account: identity.slug,
722						accessToken: identity.credentials.claudeAiOauth.accessToken,
723						expiresAt: identity.credentials.claudeAiOauth.expiresAt,
724						...(identity.credentials.claudeAiOauth.scopes
725							? { scopes: identity.credentials.claudeAiOauth.scopes }
726							: {}),
727					});
728				}
729			} catch (error) {
730				this.deps.log.warn("Could not read machine-default Claude credentials", {
731					error,
732				});
733			}
734	
735			const rows = this.deps.db
736				.select({
737					id: workspaces.id,
738					claudeAccountSlug: workspaces.claudeAccountSlug,
739				})
740				.from(workspaces)
741				.where(isNull(workspaces.archivedAt))
742				.all();
743			const hasPinnedWorkspace = rows.some(
744				(row) => row.claudeAccountSlug !== null,
745			);
746			const triggers = hasPinnedWorkspace
747				? await this.fallback.readTriggers()
748				: null;
749			const rosterRequired =
750				rows.some((row) => this.workspaceNeedsRoster(row, identity)) ||
751				triggers !== null ||
752				this.tickCount % ROSTER_REFRESH_EVERY_TICKS === 0;
753			let roster: PiAccount[] | null = null;
754			if (this.configured && rosterRequired) {
755				try {
756					roster = await this.pi.fetchAccounts();
757					this.setWarningCause(null, "pi-roster", null);
758				} catch (error) {
759					this.setWarningCause(
760						null,
761						"pi-roster",
762						"Claude account management cannot reach the Pi. Workspaces will keep their last-good credentials.",
763					);
764					this.deps.log.warn(
765						"Claude account roster refresh failed; preserving last-good state",
766						{
767							error,
768						},
769					);
770				}
771			} else {
772				this.setWarningCause(null, "pi-roster", null);
773			}
774			await mapConcurrent(rows, WORKSPACE_REFRESH_CONCURRENCY, (row) =>
775				this.refreshWorkspace(row.id, identity, roster),
776			);
777			this.clearGlobalRenewalWarningIfHealthy(rows.map((row) => row.id));
778			if (roster && triggers) {
779				await this.runFallbacks(rows, identity, roster, triggers);
780			}
781	
782			if (this.tickCount % 60 === 0) {
783				await this.requireJanitor().run(false);
784			}
785		}
786	
787		private workspaceNeedsRoster(
788			row: { id: string; claudeAccountSlug: string | null },
789			identity: GlobalIdentity | null,
790		): boolean {
791			const tokenSlug =
792				row.claudeAccountSlug ??
793				(identity?.kind === "tray" ? identity.slug : null);
794			if (!tokenSlug) return false;
795			const credentials = this.credentialCache.get(row.id);
796			return (
797				!credentials ||
798				credentials.trayManagedAccount !== tokenSlug ||
799				credentials.claudeAiOauth.expiresAt - Date.now() <= RENEW_HEADROOM_MS
800			);
801		}
802	
803		private async refreshWorkspace(
804			workspaceId: string,
805			identity: GlobalIdentity | null,
806			roster: PiAccount[] | null,
807		): Promise<void> {
808			try {
809				await this.withWorkspaceLock(
810					workspaceId,
811					async () => {
812						const row = this.deps.db.query.workspaces
813							.findFirst({ where: eq(workspaces.id, workspaceId) })
814							.sync();
815						if (!row || row.archivedAt !== null) return;
816						if (!(await this.profiles.profileExists(workspaceId))) return;
817						const current = await this.readProfileCredentialsForCache(
818							workspaceId,
819							true,
820							true,
821						);
822						if (row.claudeAccountSlug === null) {
823							await this.refreshFollowing(workspaceId, identity, roster, current);
824						} else {
825							await this.refreshPinned(
826								workspaceId,
827								row.claudeAccountSlug,
828								roster,
829								current,
830							);
831						}
832					},
833					{ tryOnly: true },
834				);
835			} catch (error) {
836				if (error instanceof WorkspaceLockBusyError) {
837					this.deps.log.info("Claude keep-fresh skipped locked workspace", {
838						workspaceId,
839					});
840					return;
841				}
842				this.deps.log.error("Claude keep-fresh failed for workspace", {
843					workspaceId,
844					error,
845				});
846			}
847		}
848	
849		private async refreshFollowing(
850			workspaceId: string,
851			identity: GlobalIdentity | null,
852			roster: PiAccount[] | null,
853			current: ManagedCredentials | null,
854		): Promise<void> {
855			if (!identity || identity.kind === "absent") {
856				this.setWarningCause(
857					workspaceId,
858					"machine-default",
859					"The machine default is signed out or unreadable. This workspace is using its last-good token.",
860				);
861				return;
862			}
863			this.setWarningCause(workspaceId, "machine-default", null);
864			if (identity.kind === "unmanaged") {
865				if (!sameAccessToken(current, identity.credentials)) {
866					await this.applyWorkspaceAccountTransition(workspaceId, {
867						desiredSlug: null,
868						credentialAction: "write",
869						credentials: identity.credentials,
870						cause: "system",
871					});
872				}
873				this.setWarningCause(
874					workspaceId,
875					"unmanaged",
876					"This workspace is following a personal Claude login. Superset can mirror its access token but cannot renew it.",
877				);
878				this.setWarningCause(workspaceId, "renewal", null);
879				return;
880			}
881			this.setWarningCause(workspaceId, "unmanaged", null);
882			if (!sameAccessToken(current, identity.credentials)) {
883				await this.applyWorkspaceAccountTransition(workspaceId, {
884					desiredSlug: null,
885					credentialAction: "write",
886					credentials: identity.credentials,
887					cause: "system",
888				});
889				current = identity.credentials;
890			}
891			const account = roster
892				? findClaudeAccount(roster, identity.slug)
893				: undefined;
894			if (roster && !account) {
895				this.setWarningCause(
896					workspaceId,
897					"roster",
898					`The machine-default Claude account '${identity.slug}' is missing from the Pi roster. The last-good token is unchanged.`,
899				);
900				return;
901			}
902			if (roster) this.setWarningCause(workspaceId, "roster", null);
903			const accountHealth = account
904				? accountHealthMessage(
905						account,
906						`The machine-default Claude account '${identity.slug}'`,
907					)
908				: null;
909			if (accountHealth) {
910				this.setWarningCause(workspaceId, "account-health", accountHealth);
911				return;
912			}
913			if (account) this.setWarningCause(workspaceId, "account-health", null);
914			if (
915				current?.trayManagedAccount !== identity.slug ||
916				current.claudeAiOauth.expiresAt - Date.now() <= RENEW_HEADROOM_MS
917			) {
918				await this.renewWorkspace(workspaceId, null, identity.slug);
919			} else {
920				this.setWarningCause(workspaceId, "renewal", null);
921			}
922		}
923	
924		private async refreshPinned(
925			workspaceId: string,
926			slug: string,
927			roster: PiAccount[] | null,
928			current: ManagedCredentials | null,
929		): Promise<void> {
930			this.setWarningCause(workspaceId, "machine-default", null);
931			this.setWarningCause(workspaceId, "unmanaged", null);
932			if (current && current.trayManagedAccount !== slug) {
933				await this.applyWorkspaceAccountTransition(workspaceId, {
934					desiredSlug: slug,
935					credentialAction: "remove",
936					cause: "system",
937				});
938				current = null;
939				this.deps.log.warn(
940					"Removed mismatched Claude credentials from pinned workspace profile",
941					{ workspaceId, pinnedSlug: slug },
942				);
943			}
944			const account = roster ? findClaudeAccount(roster, slug) : undefined;
945			if (roster && !account) {
946				this.setWarningCause(
947					workspaceId,
948					"roster",
949					`Pinned Claude account '${slug}' is missing from the Pi roster. The last-good token is unchanged.`,
950				);
951				return;
952			}
953			if (roster) this.setWarningCause(workspaceId, "roster", null);
954			const accountHealth = account
955				? accountHealthMessage(account, `Pinned Claude account '${slug}'`)
956				: null;
957			if (accountHealth) {
958				this.setWarningCause(workspaceId, "account-health", accountHealth);
959				return;
960			}
961			if (account) this.setWarningCause(workspaceId, "account-health", null);
962			if (
963				current?.trayManagedAccount === slug &&
964				current.claudeAiOauth.expiresAt - Date.now() > RENEW_HEADROOM_MS
965			) {
966				this.setWarningCause(workspaceId, "renewal", null);
967				return;
968			}
969			await this.renewWorkspace(workspaceId, slug, slug);
970		}
971	
972		private async renewWorkspace(
973			workspaceId: string,
974			desiredSlug: string | null,
975			tokenSlug: string,
976		): Promise<void> {
977			try {
978				const token = await this.fetchTokenWithBackoff(tokenSlug);
979				await this.applyWorkspaceAccountTransition(workspaceId, {
980					desiredSlug,
981					credentialAction: "write",
982					credentials: credentialsFromToken(token),
983					cause: "system",
984				});
985				this.setWarningCause(workspaceId, "renewal", null);
986			} catch (error) {
987				this.setWarningCause(
988					workspaceId,
989					"renewal",
990					`Claude token renewal failed for '${tokenSlug}'. This workspace is using its last-good token.`,
991				);
992				this.setWarningCause(
993					null,
994					"pi-renewal",
995					"Claude account token renewal is failing. Workspaces will keep their last-good credentials.",
996				);
997				this.deps.log.warn(
998					"Claude token renewal failed; preserving last-good credentials",
999					{
1000						workspaceId,
1001						slug: tokenSlug,
1002						error,
1003					},
1004				);
1005			}
1006		}
1007	
1008		private async runFallbacks(
1009			rows: Array<{ id: string; claudeAccountSlug: string | null }>,
1010			identity: GlobalIdentity | null,
1011			roster: PiAccount[],
1012			triggers: TrayTriggers,
1013		): Promise<void> {
1014			if (!identity || identity.kind !== "tray") {
1015				for (const row of rows) {
1016					if (row.claudeAccountSlug !== null) {
1017						this.deps.log.info(
1018							"Claude auto-fallback suppressed: machine default identity is unknown",
1019							{ workspaceId: row.id },
1020						);
1021					}
1022				}
1023				return;
1024			}
1025			const defaultAccount = findClaudeAccount(roster, identity.slug);
1026			if (!defaultAccount) {
1027				this.deps.log.warn(
1028					"Claude auto-fallback suppressed: machine default is missing from the Pi roster",
1029					{ machineDefaultSlug: identity.slug },
1030				);
1031				return;
1032			}
1033			const defaultAccountHealth = accountHealthMessage(
1034				defaultAccount,
1035				`The machine-default Claude account '${identity.slug}'`,
1036			);
1037			if (defaultAccountHealth) {
1038				for (const row of rows) {
1039					if (row.claudeAccountSlug === null) continue;
1040					this.setWarningCause(row.id, "account-health", defaultAccountHealth);
1041				}
1042				this.deps.log.warn(
1043					"Claude auto-fallback suppressed: machine default is unavailable",
1044					{ machineDefaultSlug: identity.slug },
1045				);
1046				return;
1047			}
1048			const candidates: Array<{
1049				workspaceId: string;
1050				pinnedSlug: string;
1051				reason: string;
1052			}> = [];
1053			for (const row of rows) {
1054				const slug = row.claudeAccountSlug;
1055				if (slug === null) continue;
1056				if (slug === identity.slug) {
1057					this.deps.log.info(
1058						"Claude auto-fallback suppressed: pinned account is the machine default",
1059						{ workspaceId: row.id, slug },
1060					);
1061					continue;
1062				}
1063				const account = findClaudeAccount(roster, slug);
1064				if (!account) {
1065					this.deps.log.warn(
1066						"Claude auto-fallback suppressed: pinned account is absent from roster",
1067						{ workspaceId: row.id, slug },
1068					);
1069					continue;
1070				}
1071				const evaluation = this.fallback.evaluate(account, triggers);
1072				if (evaluation.action === "suppress") {
1073					const accountHealth = accountHealthMessage(
1074						account,
1075						`Pinned Claude account '${slug}'`,
1076					);
1077					if (accountHealth) {
1078						this.setWarningCause(row.id, "account-health", accountHealth);
1079					}
1080					this.deps.log.info("Claude auto-fallback suppressed", {
1081						workspaceId: row.id,
1082						slug,
1083						reason: evaluation.reason,
1084					});
1085					continue;
1086				}
1087				candidates.push({
1088					workspaceId: row.id,
1089					pinnedSlug: slug,
