1200			if (backoff && backoff.nextAttemptAt > Date.now()) {
1201				throw new Error(
1202					`Token fetch for ${slug} is backed off until ${new Date(backoff.nextAttemptAt).toISOString()}`,
1203				);
1204			}
1205			try {
1206				const token = await this.pi.fetchToken(slug);
1207				this.tokenBackoffs.delete(slug);
1208				return token;
1209			} catch (error) {
1210				const failures = (backoff?.failures ?? 0) + 1;
1211				const delay = Math.min(
1212					TICK_INTERVAL_MS * 2 ** Math.min(failures - 1, 8),
1213					MAX_TOKEN_BACKOFF_MS,
1214				);
1215				this.tokenBackoffs.set(slug, {
1216					failures,
1217					nextAttemptAt: Date.now() + delay,
1218				});
1219				throw error;
1220			}
1221		}
