1223		private credentialsForPinnedLaunch(
1224			workspaceId: string,
1225			slug: string,
1226			current: ManagedCredentials | null,
1227		): CredentialTransition {
1228			if (
1229				current?.trayManagedAccount === slug &&
1230				current.claudeAiOauth.accessToken
1231			) {
1232				this.setWarningCause(workspaceId, "renewal", null);
1233				return { credentialAction: "write", credentials: current };
1234			}
1235			const lastGood = this.pi.getTokenLastGood(slug);
1236			if (lastGood) {
1237				this.setWarningCause(workspaceId, "renewal", null);
1238				return {
1239					credentialAction: "write",
1240					credentials: credentialsFromToken(lastGood),
1241				};
1242			}
1243			this.setWarningCause(
1244				workspaceId,
1245				"renewal",
1246				`Pinned Claude account '${slug}' has no last-good token. The workspace profile is intentionally credential-less until keep-fresh recovers.`,
1247				{ emit: true },
1248			);
1249			return { credentialAction: "remove" };
1250		}
