1306		private async readProfileCredentialsForCache(
1307			workspaceId: string,
1308			knownExists?: boolean,
1309			revalidate = false,
1310		): Promise<ManagedCredentials | null> {
1311			const profileExists =
1312				knownExists ?? (await this.profiles.profileExists(workspaceId));
1313			if (!profileExists) {
1314				this.credentialCache.delete(workspaceId);
1315				return null;
1316			}
1317			// revalidate: the CLI can blank the file on disk underneath a warm cache
1318			// entry (failed refresh); the keep-fresh tick re-reads so that state is
1319			// detected and repaired instead of trusted away.
1320			if (!revalidate && this.credentialCache.has(workspaceId)) {
1321				return this.credentialCache.get(workspaceId) ?? null;
1322			}
1323			try {
1324				const credentials =
1325					await this.profiles.readProfileCredentials(workspaceId);
1326				if (credentials) this.cacheCredentials(workspaceId, credentials);
1327				else this.credentialCache.set(workspaceId, null);
1328				return credentials;
1329			} catch (error) {
1330				this.credentialCache.set(workspaceId, null);
1331				if (error instanceof BlankedCredentialsError) {
1332					this.deps.log.error(
1333						"Claude blanked this workspace's managed credentials; rewriting them",
1334						{
1335							workspaceId,
1336							trayManagedAccount: error.trayManagedAccount,
1337							path: error.path,
1338						},
1339					);
1340					this.setWarningCause(
1341						workspaceId,
1342						"blanked",
1343						"A failed Claude token refresh emptied this workspace's credentials. Superset is restoring them from the Pi.",
1344					);
1345					return null;
1346				}
1347				this.deps.log.warn(
1348					"Existing Claude profile credentials could not seed last-good cache",
1349					{
1350						workspaceId,
1351						error,
1352					},
1353				);
1354				return null;
1355			}
1356		}
