1358		private cacheCredentials(
1359			workspaceId: string,
1360			credentials: ManagedCredentials,
1361		): void {
1362			this.credentialCache.set(workspaceId, credentials);
1363			if (credentials.trayManagedAccount) {
1364				this.pi.rememberToken({
1365					account: credentials.trayManagedAccount,
1366					accessToken: credentials.claudeAiOauth.accessToken,
1367					expiresAt: credentials.claudeAiOauth.expiresAt,
1368				});
1369			}
