1372		private async applyWorkspaceAccountTransition(
1373			workspaceId: string,
1374			transition: AccountTransition,
1375		): Promise<boolean> {
1376			if (!transition.database) {
1377				await this.applyCredentialTransition(workspaceId, transition);
1378				return true;
1379			}
1380	
1381			const priorCredentialState = await this.profiles.captureCredentialFileState(
1382				this.profiles.profileDirFor(workspaceId),
1383			);
1384			await this.applyCredentialTransition(workspaceId, transition);
1385			let updated: { id: string } | undefined;
1386			try {
1387				if (transition.database.kind === "set") {
1388					updated = this.deps.db
1389						.update(workspaces)
1390						.set({ claudeAccountSlug: transition.desiredSlug })
1391						.where(eq(workspaces.id, workspaceId))
1392						.returning({ id: workspaces.id })
1393						.get();
1394				} else {
1395					updated = this.deps.db
1396						.update(workspaces)
1397						.set({ claudeAccountSlug: transition.desiredSlug })
1398						.where(
1399							and(
1400								eq(workspaces.id, workspaceId),
1401								eq(
1402									workspaces.claudeAccountSlug,
1403									transition.database.expectedSlug,
1404								),
1405							),
1406						)
1407						.returning({ id: workspaces.id })
1408						.get();
1409				}
1410			} catch (error) {
1411				await this.restoreCredentialStateAfterDatabaseFailure(
1412					workspaceId,
1413					priorCredentialState,
1414					error,
1415				);
1416				throw error;
1417			}
1418			if (!updated) {
1419				await this.restoreCredentialStateAfterDatabaseFailure(
1420					workspaceId,
1421					priorCredentialState,
1422					new Error("Workspace account database compare-and-set did not update"),
1423				);
1424				return false;
1425			}
1426	
1427			this.setWarningCause(workspaceId, "credential-compensation", null);
1428			this.setWarningCause(workspaceId, "renewal", null);
1429			this.setWarningCause(workspaceId, "roster", null);
1430			this.setWarningCause(workspaceId, "account-health", null);
1431			if (transition.desiredSlug !== null) {
1432				this.setWarningCause(workspaceId, "machine-default", null);
1433				this.setWarningCause(workspaceId, "unmanaged", null);
1434			}
1435			const stateChanged =
1436				transition.database.kind === "compare-and-set" ||
1437				transition.database.currentSlug !== transition.desiredSlug;
1438			if (stateChanged) {
1439				this.deps.emit({
1440					type: "claude-account-state-changed",
1441					workspaceId,
1442					state: transition.desiredSlug === null ? "following" : "pinned",
1443					slug: transition.desiredSlug,
1444					cause: transition.cause,
1445				});
1446			}
1447			return true;
1448		}
