1450		private async applyCredentialTransition(
1451			workspaceId: string,
1452			transition: AccountTransition,
1453		): Promise<void> {
1454			if (transition.ensureProfile) {
1455				await this.profiles.mintProfile(
1456					workspaceId,
1457					transition.ensureProfile.worktreePath,
1458					null,
1459					transition.ensureProfile.knownExists,
1460				);
1461			}
1462			switch (transition.credentialAction) {
1463				case "write":
1464					await this.writeWorkspaceCredentials(
1465						workspaceId,
1466						transition.credentials,
1467					);
1468					return;
1469				case "remove":
1470					await this.removeWorkspaceCredentials(workspaceId);
1471					return;
1472				case "keep":
1473					return;
1474			}
1475		}
