1555			workspaceIds: readonly string[],
1556			originalError: unknown,
1557		): Promise<void> {
1558			const janitor = this.requireJanitor();
1559			const clearResults = await Promise.allSettled(
1560				workspaceIds.map((workspaceId) =>
1561					janitor.clearDeletionMarker(workspaceId),
