1587		private async deleteProfileWithTerminalIds(
1588			workspaceId: string,
1589			terminalIds: readonly string[],
1590		): Promise<void> {
1591			const disposalOptions = this.disposalOptions("warn-and-continue");
1592			await disposeTerminalIds(this.deps.db, terminalIds, disposalOptions);
1593			try {
1594				await this.profiles.deleteProfileDir(workspaceId);
1595			} catch (error) {
1596				if (!isBusyFsError(error)) throw error;
1597				const retryIds = [
1598					...terminalIds,
1599					...listUndisposedTerminalIdsByWorkspaceId(workspaceId, this.deps.db),
1600				];
1601				await disposeTerminalIds(this.deps.db, retryIds, disposalOptions);
1602				await this.profiles.deleteProfileDir(workspaceId);
1603			}
1604			this.credentialCache.delete(workspaceId);
1605			for (const cause of this.warningCauses.get(workspaceId)?.keys() ?? []) {
1606				this.setWarningCause(workspaceId, cause, null, { emit: false });
1607			}
1608			const referencedSlugs = new Set(
1609				this.deps.db
1610					.select({ slug: workspaces.claudeAccountSlug })
1611					.from(workspaces)
1612					.all()
1613					.flatMap((row) => (row.slug ? [row.slug] : [])),
1614			);
1615			for (const credentials of this.credentialCache.values()) {
1616				if (credentials?.trayManagedAccount) {
1617					referencedSlugs.add(credentials.trayManagedAccount);
1618				}
1619			}
1620			for (const slug of this.tokenBackoffs.keys()) {
1621				if (!referencedSlugs.has(slug)) this.tokenBackoffs.delete(slug);
1622			}
1623		}
