1727		private startCredentialsWatcher(): void {
1728			const parent = dirname(this.profiles.globalCredentialsPath);
1729			const filename = basename(this.profiles.globalCredentialsPath);
1730			try {
1731				this.credentialsWatcher = watch(parent, (eventType, changed) => {
1732					if (changed?.toString() !== filename) return;
1733					this.deps.log.info("Machine-default Claude credentials changed", {
1734						eventType,
1735					});
1736					const followingRows = this.deps.db
1737						.select({ id: workspaces.id })
1738						.from(workspaces)
1739						.where(isNull(workspaces.claudeAccountSlug))
1740						.all();
1741					for (const row of followingRows) this.credentialCache.delete(row.id);
1742					void this.runTick().catch((error) => {
1743						this.deps.log.error("Claude credential mirror tick failed", {
1744							error,
1745						});
1746					});
1747				});
1748				this.credentialsWatcher.on("error", (error) => {
1749					this.deps.log.warn(
1750						"Machine-default Claude credential watcher failed; 60-second polling remains active",
1751						{ error },
1752					);
1753				});
1754			} catch (error) {
1755				this.deps.log.warn(
1756					"Could not start machine-default Claude credential watcher; 60-second polling remains active",
1757					{ error },
1758				);
1759			}
1760		}
