1762		private setWarningCause(
1763			workspaceId: string | null,
1764			cause: string,
1765			message: string | null,
1766			options?: { emit?: boolean },
1767		): void {
1768			const key = workspaceId ?? GLOBAL_WARNING_KEY;
1769			const previous = this.renderWarning(workspaceId);
1770			let causes = this.warningCauses.get(key);
1771			if (!causes) {
1772				causes = new Map();
1773				this.warningCauses.set(key, causes);
1774			}
1775			if (message === null) causes.delete(cause);
1776			else causes.set(cause, message);
1777			if (causes.size === 0) this.warningCauses.delete(key);
1778			const rendered = this.renderWarning(workspaceId);
1779			const emit =
1780				options?.emit ??
1781				(workspaceId === null || !SILENT_WORKSPACE_CAUSES.has(cause));
1782			if (rendered === previous || !emit) return;
1783			const eventMessage = rendered ?? previous;
1784			if (eventMessage === null) return;
1785			this.deps.emit({
1786				type: "claude-account-warning",
1787				workspaceId,
1788				kind: "credential-health",
1789				message: eventMessage,
1790				active: rendered !== null,
1791			});
1792		}
