1807		private renderWarning(workspaceId: string | null): string | null {
1808			const key = workspaceId ?? GLOBAL_WARNING_KEY;
1809			const messages = [...(this.warningCauses.get(key)?.values() ?? [])];
1810			if (workspaceId !== null && this.managed && !this.configured) {
1811				messages.push(
1812					"The Pi push key is unavailable. This workspace will keep its last-good Claude token.",
1813				);
1814			}
1815			return messages.length > 0 ? messages.join(" ") : null;
