420		deleted: Array<{ workspaceId: string; terminalIds: readonly string[] }>;
421	}> {
422		const manager = new ClaudeProfileManager(world.dbPath, world.log);
423		await manager.initialize();
424		const locks = new WorkspaceLocks();
425		const deleted: Array<{
426			workspaceId: string;
427			terminalIds: readonly string[];
428		}> = [];
429		const janitor = new ClaudeProfileJanitor({
430			db: world.db,
431			dbInstanceId: options.dbInstanceId ?? DB_INSTANCE_ID,
432			profiles: manager,
433			log: world.log,
434			withWorkspaceLock: async (workspaceId, fn, lockOptions) => {
435				await options.beforeLock?.(workspaceId);
436				return locks.withLock(workspaceId, fn, lockOptions);
437			},
438			deleteProfileWithTerminalIds: async (workspaceId, terminalIds) => {
439				deleted.push({ workspaceId, terminalIds: [...terminalIds] });
440				await manager.deleteProfileDir(workspaceId);
441			},
442		});
443		return { manager, janitor, deleted };
444	}
