1514		private async readProfileCredentialsForCache(
1515			workspaceId: string,
1516			knownExists?: boolean,
1517			revalidate = false,
1518		): Promise<ManagedCredentials | null> {
1519			const profileExists =
1520				knownExists ?? (await this.profiles.profileExists(workspaceId));
1521			if (!profileExists) {
1522				this.credentialCache.delete(workspaceId);
1523				return null;
1524			}
1525			// revalidate: the CLI can blank the file on disk underneath a warm cache
1526			// entry (failed refresh); the keep-fresh tick re-reads so that state is
1527			// detected and repaired instead of trusted away.
1528			if (!revalidate && this.credentialCache.has(workspaceId)) {
1529				return this.credentialCache.get(workspaceId) ?? null;
1530			}
1531			try {
1532				const credentials =
1533					await this.profiles.readProfileCredentials(workspaceId);
1534				if (credentials) this.cacheCredentials(workspaceId, credentials);
1535				else this.credentialCache.set(workspaceId, null);
1536				return credentials;
1537			} catch (error) {
1538				this.credentialCache.set(workspaceId, null);
1539				if (error instanceof BlankedCredentialsError) {
1540					this.deps.log.error(
1541						"Claude blanked this workspace's managed credentials; rewriting them",
1542						{
1543							workspaceId,
1544							trayManagedAccount: error.trayManagedAccount,
1545							path: error.path,
1546						},
1547					);
1548					this.setWarningCause(
1549						workspaceId,
1550						"blanked",
1551						"A failed Claude token refresh emptied this workspace's credentials. Superset is restoring them from the Pi.",
1552					);
1553					return null;
1554				}
1555				this.deps.log.warn(
1556					"Existing Claude profile credentials could not seed last-good cache",
1557					{
1558						workspaceId,
1559						error,
1560					},
1561				);
1562				return null;
1563			}
1564		}
