1566		private cacheCredentials(
1567			workspaceId: string,
1568			credentials: ManagedCredentials,
1569		): void {
1570			this.credentialCache.set(workspaceId, credentials);
1571			if (credentials.trayManagedAccount) {
1572				this.pi.rememberToken({
1573					account: credentials.trayManagedAccount,
1574					accessToken: credentials.claudeAiOauth.accessToken,
1575					expiresAt: credentials.claudeAiOauth.expiresAt,
1576				});
1577			}
1578		}
