1580		private async applyWorkspaceAccountTransition(
1581			workspaceId: string,
1582			transition: AccountTransition,
1583		): Promise<boolean> {
1584			if (!transition.database) {
1585				await this.applyCredentialTransition(workspaceId, transition);
1586				return true;
1587			}
1588	
1589			const priorCredentialState = await this.profiles.captureCredentialFileState(
1590				this.profiles.profileDirFor(workspaceId),
1591			);
1592			await this.applyCredentialTransition(workspaceId, transition);
1593			let updated: { id: string } | undefined;
1594			try {
1595				if (transition.database.kind === "set") {
1596					updated = this.deps.db
1597						.update(workspaces)
1598						.set({ claudeAccountSlug: transition.desiredSlug })
1599						.where(eq(workspaces.id, workspaceId))
1600						.returning({ id: workspaces.id })
1601						.get();
1602				} else {
1603					updated = this.deps.db
1604						.update(workspaces)
1605						.set({ claudeAccountSlug: transition.desiredSlug })
1606						.where(
1607							and(
1608								eq(workspaces.id, workspaceId),
1609								eq(
1610									workspaces.claudeAccountSlug,
1611									transition.database.expectedSlug,
1612								),
1613							),
1614						)
1615						.returning({ id: workspaces.id })
1616						.get();
1617				}
1618			} catch (error) {
1619				await this.restoreCredentialStateAfterDatabaseFailure(
1620					workspaceId,
1621					priorCredentialState,
1622					error,
1623				);
1624				throw error;
1625			}
1626			if (!updated) {
1627				await this.restoreCredentialStateAfterDatabaseFailure(
1628					workspaceId,
1629					priorCredentialState,
1630					new Error("Workspace account database compare-and-set did not update"),
1631				);
1632				return false;
1633			}
1634	
1635			this.setWarningCause(workspaceId, "credential-compensation", null);
1636			this.setWarningCause(workspaceId, "renewal", null);
1637			this.setWarningCause(workspaceId, "account-switch", null);
1638			this.setWarningCause(workspaceId, "roster", null);
1639			this.setWarningCause(workspaceId, "account-health", null);
1640			if (transition.desiredSlug !== null) {
1641				this.setWarningCause(workspaceId, "machine-default", null);
1642				this.setWarningCause(workspaceId, "unmanaged", null);
1643			}
1644			const stateChanged =
1645				transition.database.kind === "compare-and-set" ||
1646				transition.database.currentSlug !== transition.desiredSlug;
1647			if (stateChanged) {
1648				this.pruneUnreferencedTokenState();
